import sys, re, io, tokenize
# usage: rn.py FILE rule... ; rule: [.]old=new[@a-b]  (line range inclusive)
path, rules = sys.argv[1], []
for r in sys.argv[2:]:
    m = re.fullmatch(r"(\.?)(\w+)=(\w+)(?:@(\d+)-(\d+))?", r)
    assert m, r
    rules.append((bool(m[1]), m[2], m[3], int(m[4] or 0), int(m[5] or 10**9)))
src = open(path).read()
lines = src.split("\n")
def hit(attr, name, ln):
    for a, o, n, lo, hi in rules:
        if o == name and lo <= ln <= hi and (a or not attr):
            return n
if path.endswith((".ts", ".tsx")):
    out = []
    for ln, line in enumerate(lines, 1):
        def sub(m):
            attr = m.start() > 0 and line[m.start()-1] == "."
            return hit(attr, m[0], ln) or m[0]
        out.append(re.sub(r"(?<![\w$])[A-Za-z_]\w*", sub, line))
    open(path, "w").write("\n".join(out))
else:
    toks = list(tokenize.generate_tokens(io.StringIO(src).readline))
    edits = []
    prev = None
    for t in toks:
        if t.type == tokenize.NAME:
            n = hit(prev is not None and prev.string == ".", t.string, t.start[0])
            if n: edits.append((t.start, t.end, n))
        if t.type not in (tokenize.NL, tokenize.COMMENT): prev = t
    for (r, c), (r2, c2), n in reversed(edits):
        l = lines[r-1]; lines[r-1] = l[:c] + n + l[c2:]
    open(path, "w").write("\n".join(lines))
EOF
