import sys, dis, builtins, ast
for path in sys.argv[1:]:
    src = open(path).read()
    tree = ast.parse(src)
    defined = set(dir(builtins)) | {"__file__", "__doc__", "__name__"}
    for n in ast.walk(tree):
        if isinstance(n, (ast.FunctionDef, ast.ClassDef, ast.AsyncFunctionDef)) and n in tree.body: defined.add(n.name)
        if isinstance(n, ast.Import): defined |= {(a.asname or a.name).split(".")[0] for a in n.names}
        if isinstance(n, ast.ImportFrom): defined |= {a.asname or a.name for a in n.names}
    for n in ast.walk(tree):  # module-level names incl. global stmts: all Store names anywhere at module scope or declared global
        if isinstance(n, ast.Global): defined |= set(n.names)
    for n in tree.body:
        for m in ast.walk(n) if not isinstance(n,(ast.FunctionDef,ast.ClassDef,ast.AsyncFunctionDef)) else []:
            if isinstance(m, ast.Name) and isinstance(m.ctx, ast.Store): defined.add(m.id)
    code = compile(src, path, "exec")
    stack = [code]
    while stack:
        c = stack.pop()
        for ins in dis.get_instructions(c):
            if ins.opname in ("LOAD_GLOBAL", "LOAD_NAME") and ins.argval not in defined:
                print(f"{path}:{ins.positions.lineno if ins.positions else '?'} {ins.argval}")
        stack += [k for k in c.co_consts if hasattr(k, "co_code")]
EOF
